// 精简统计：openviking pending 文件数与 grill-first 记忆（不打印全列表）
const r = await tools.pwsh({
  command: `
Write-Host ("openviking pending 文件数: " + (Get-ChildItem "$env:USERPROFILE\\.openviking\\pending" -File -ErrorAction SilentlyContinue).Count)
Write-Host ("openviking state 项: ")
Get-ChildItem "$env:USERPROFILE\\.openviking\\state" -ErrorAction SilentlyContinue | Select-Object Name | Out-String
Write-Host '=== grill-first 记忆目录 ==='
Get-ChildItem "$env:DSH_HOME\\grill-first" -Recurse -Depth 1 -ErrorAction SilentlyContinue | Select-Object FullName, Length | Format-Table -AutoSize | Out-String
`,
  description: "统计 openviking 记忆规模与 grill-first 数据"
});
console.log(r.stdout);
